import java.util.ArrayList;
import java.util.Arrays;

final class Distances {
    private final int[] values;

    private Distances(int[] values) {
        this.values = values;
    }

    static Distances forSource(int vertexCount, int source) {
        if (source < 0 || source >= vertexCount) {
            throw new IndexOutOfBoundsException("source out of range: " + source);
        }

        int[] values = new int[vertexCount];
        Arrays.fill(values, Integer.MAX_VALUE);
        values[source] = 0;
        return new Distances(values);
    }

    boolean isStale(QueueEntry entry) {
        return entry.distance() > values[entry.vertex()];
    }

    boolean tryUpdate(int vertex, int distance) {
        if (distance >= values[vertex]) {
            return false;
        }

        values[vertex] = distance;
        return true;
    }

    ArrayList<Integer> toList() {
        ArrayList<Integer> result = new ArrayList<>(values.length);
        for (int value : values) {
            result.add(value);
        }
        return result;
    }
}

import java.util.Comparator;
import java.util.PriorityQueue;

final class ShortestPathSolver {
    private final Graph graph;
    private final Distances distances;
    private final PriorityQueue<QueueEntry> minHeap;

    private ShortestPathSolver(Graph graph, int source) {
        if (graph == null) {
            throw new IllegalArgumentException("graph must not be null");
        }

        this.graph = graph;
        this.distances = Distances.forSource(graph.vertexCount(), source);
        this.minHeap = new PriorityQueue<>(Comparator.comparingInt(QueueEntry::distance));
        this.minHeap.offer(new QueueEntry(source, 0));
    }

    static Distances solve(Graph graph, int source) {
        return new ShortestPathSolver(graph, source).run();
    }

    private Distances run() {
        while (!minHeap.isEmpty()) {
            QueueEntry current = minHeap.poll();
            if (distances.isStale(current)) {
                continue;
            }

            relaxNeighborsOf(current);
        }
        return distances;
    }

    private void relaxNeighborsOf(QueueEntry current) {
        for (Edge edge : graph.neighborsOf(current.vertex())) {
            tryRelax(current, edge);
        }
    }

    private void tryRelax(QueueEntry current, Edge edge) {
        if (current.distance() == Integer.MAX_VALUE) {
            return;
        }

        long candidateDistance = (long) current.distance() + edge.weight();
        if (candidateDistance > Integer.MAX_VALUE) {
            return;
        }

        int nextDistance = (int) candidateDistance;
        if (distances.tryUpdate(edge.to(), nextDistance)) {
            minHeap.offer(new QueueEntry(edge.to(), nextDistance));
        }
    }
}

import java.util.ArrayList;
import java.util.List;

public final class ShortestPathTest {
    private ShortestPathTest() {
    }

    public static void main(String[] args) {
        verifiesSampleGraphDistances();
        verifiesBuilderChainingBuildsGraph();
        verifiesUnreachableVerticesRemainInfinite();
        System.out.println("All ShortestPath tests passed");
    }

    private static void verifiesSampleGraphDistances() {
        List<Integer> distances = ShortestPath.shortestPaths(SampleGraphs.weightedUndirectedExample(), 0);
        assertDistances("sample graph", distances, 0, 4, 7, 9, 10);
    }

    private static void verifiesBuilderChainingBuildsGraph() {
        Graph graph = GraphBuilder.withVertexCount(3)
            .addUndirectedEdge(0, 1, 2)
            .addUndirectedEdge(1, 2, 1)
            .build();

        List<Integer> distances = ShortestPath.shortestPaths(graph, 0);
        assertDistances("builder chaining", distances, 0, 2, 3);
    }

    private static void verifiesUnreachableVerticesRemainInfinite() {
        Graph graph = GraphBuilder.withVertexCount(3)
            .addUndirectedEdge(0, 1, 5)
            .build();

        List<Integer> distances = ShortestPath.shortestPaths(graph, 0);
        assertDistances("unreachable vertex", distances, 0, 5, Integer.MAX_VALUE);
    }

    private static void assertDistances(String label, List<Integer> actual, int... expected) {
        List<Integer> expectedDistances = new ArrayList<>(expected.length);
        for (int value : expected) {
            expectedDistances.add(value);
        }

        if (!actual.equals(expectedDistances)) {
            throw new AssertionError(
                label + " distances mismatch. expected=" + expectedDistances + " actual=" + actual
            );
        }
    }
}

